182	
183	// 拒绝保持原子性：即使异常出现在后面的帧，前面暂存的位姿、新路标和观测
184	// 次数都不可见；已提交地图和本地数据文件保持原样；失败不消耗段标识，
185	// 也不消耗失效后再次出现的出现编号。
186	func TestImportComputedNonFiniteAtomicity(t *testing.T) {
