// 不携带路标/出现信息。
func TestCorrectionOverflowPoseKeepsAnchorError(t *testing.T) {
	m := newMap(t, Config{InitialTime: 0, MaxInterval: 100, MergeDistance: 10})
	if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
